def add_dp(add):
    add('dinamica', 'Robot: reconstruiește traseul', 'Citește n m și matricea de numere naturale. Afișează suma maximă de la (1,1) la (n,m), apoi celulele unui traseu optim, o pereche linie coloană pe linie. Sunt permise numai sud și est.', 'Memorează vecinul ales și urmărește predecesorii din destinație spre start.', 'n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\ndp = [[0] * m for _ in range(n)]\npred = {}\nfor i in range(n):\n    for j in range(m):\n        if i == j == 0:\n            dp[i][j] = a[i][j]\n        else:\n            options = [(dp[r][c], r, c) for r, c in [(i - 1, j), (i, j - 1)] if r >= 0 and c >= 0]\n            v, r, c = max(options)\n            dp[i][j] = a[i][j] + v\n            pred[i, j] = (r, c)\npath = [(n - 1, m - 1)]\nwhile path[-1] != (0, 0):\n    path.append(pred[path[-1]])\nprint(dp[-1][-1])\nfor r, c in reversed(path):\n    print(r + 1, c + 1)', [('2 2\n1 2\n3 4','8\n1 1\n2 1\n2 2'),('1 1\n7','7\n1 1'),('2 2\n1 1\n1 1','3\n1 1\n1 2\n2 2')], 'Aplicare', validator='robot')
    add('dinamica', 'Numărul traseelor optime', 'Citește n m și o matrice de numere naturale. Afișează suma maximă sud-est și numărul traseelor care o realizează.', 'Memorează și numărul de moduri. La egalitate adună numerele traseelor.', 'n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\ndp = [[0] * m for _ in range(n)]\nways = [[0] * m for _ in range(n)]\nfor i in range(n):\n    for j in range(m):\n        if i == j == 0:\n            dp[i][j], ways[i][j] = a[i][j], 1\n        else:\n            prev = [(r, c) for r, c in [(i - 1, j), (i, j - 1)] if r >= 0 and c >= 0]\n            v = max(dp[r][c] for r, c in prev)\n            dp[i][j] = v + a[i][j]\n            ways[i][j] = sum(ways[r][c] for r, c in prev if dp[r][c] == v)\nprint(dp[-1][-1], ways[-1][-1])', [('2 2\n1 1\n1 1','3 2'),('2 2\n1 2\n3 4','8 1'),('1 1\n0','0 1')], 'Aprofundare')
    add('dinamica', 'Triunghi: drumul optim', 'Citește n și n linii de triunghi. Afișează suma maximă și indicii coloanelor de la 0 ai unui traseu optim pe a doua linie. Poți coborî la aceeași coloană sau următoarea.', 'Calculează de jos în sus și memorează copilul ales.', 'n = int(input())\na = [list(map(int, input().split())) for _ in range(n)]\ndp = [row[:] for row in a]\npred = {}\nfor i in range(n - 2, -1, -1):\n    for j in range(i + 1):\n        k = j if dp[i + 1][j] >= dp[i + 1][j + 1] else j + 1\n        dp[i][j] += dp[i + 1][k]\n        pred[i, j] = k\nj = 0\npath = [0]\nfor i in range(n - 1):\n    j = pred[i, j]\n    path.append(j)\nprint(dp[0][0])\nprint(*path)', [('3\n1\n2 3\n4 5 6','10\n0 1 2'),('1\n-5','-5\n0'),('2\n1\n2 2','3\n0 0')], 'Aplicare', validator='triangle')
    add('dinamica', 'Subșir nedescrescător cu reconstrucție', 'Citește o listă de întregi. Afișează lungimea maximă a unui subșir nedescrescător (≤ între vecini), apoi valorile unui astfel de subșir.', 'Folosește ≤, nu <, și păstrează indicele predecesorului.', 'a = list(map(int, input().split()))\ndp = [1] * len(a)\npred = [-1] * len(a)\nfor i in range(len(a)):\n    for j in range(i):\n        if a[j] <= a[i] and dp[j] + 1 > dp[i]:\n            dp[i], pred[i] = dp[j] + 1, j\nk = max(range(len(a)), key=lambda i: dp[i]) if a else -1\npath = []\nwhile k != -1:\n    path.append(a[k])\n    k = pred[k]\nprint(len(path))\nprint(*reversed(path))', [('2 2 1 3','3\n2 2 3'),('\n','0\n'),('3 2 1','1\n3')], 'Aplicare', validator='lnds')
    add('dinamica', 'LIS în O(n log n)', 'Citește o listă de întregi. Afișează lungimea maximă strict crescătoare și valorile unui astfel de subșir. Folosește O(n log n) și predecesori.', 'tails[k] păstrează cel mai mic final pentru lungimea k+1; tails singur nu este mereu un subșir valid.', 'from bisect import bisect_left\na = list(map(int, input().split()))\ntails = []\nindices = []\npred = [-1] * len(a)\nfor i, x in enumerate(a):\n    k = bisect_left(tails, x)\n    if k:\n        pred[i] = indices[k - 1]\n    if k == len(tails):\n        tails.append(x)\n        indices.append(i)\n    else:\n        tails[k], indices[k] = x, i\npath = []\ni = indices[-1] if indices else -1\nwhile i != -1:\n    path.append(a[i])\n    i = pred[i]\nprint(len(path))\nprint(*reversed(path))', [('3 1 2 2 5','3\n1 2 5'),('2 2 2','1\n2'),('\n','0\n')], 'Aprofundare', validator='lis')
    add('dinamica', 'Lanț pe două litere', 'Citește cuvinte lowercase de minimum două litere. Alege un subșir în ordinea inițială cu ultimele două litere ale unui cuvânt egale cu primele două ale următorului. Afișează lungimea maximă și cuvintele unui lanț optim.', 'dp[i] este lungimea lanțului terminat la i; folosește a[j][-2:] == a[i][:2].', 'a = input().split()\ndp = [1] * len(a)\npred = [-1] * len(a)\nfor i in range(len(a)):\n    for j in range(i):\n        if a[j][-2:] == a[i][:2] and dp[j] + 1 > dp[i]:\n            dp[i], pred[i] = dp[j] + 1, j\ni = max(range(len(a)), key=lambda i: dp[i]) if a else -1\npath = []\nwhile i != -1:\n    path.append(a[i])\n    i = pred[i]\nprint(len(path))\nprint(*reversed(path))', [('masa carte sac teatru tema rustic sare','3\ncarte teatru rustic'),('abcd cdef efgh','3\nabcd cdef efgh'),('\n','0\n')], 'Aprofundare', validator='wordchain')
    add('dinamica', 'Monedele efectiv folosite', 'Citește monedele pozitive distincte și suma S ≥ 0. Afișează numărul minim și monedele folosite; dacă este imposibil, afișează numai -1. Stocurile sunt nelimitate.', 'Memorează moneda aleasă la fiecare sumă și scade-o la reconstrucție.', 'a = list(map(int, input().split()))\nS = int(input())\ndp = [0] + [S + 1] * S\npred = [0] * (S + 1)\nfor s in range(1, S + 1):\n    for c in a:\n        if c <= s and dp[s - c] + 1 < dp[s]:\n            dp[s], pred[s] = dp[s - c] + 1, c\nif dp[S] > S:\n    print(-1)\nelse:\n    print(dp[S])\n    path = []\n    while S:\n        path.append(pred[S])\n        S -= pred[S]\n    print(*path)', [('1 3 4\n6','2\n3 3'),('2 4\n3','-1'),('2 5\n0','0\n')], 'Aplicare', validator='coins')
    add('dinamica', 'Rucsac: obiectele alese', 'Citește n G și n perechi greutate valoare pozitive. Afișează valoarea maximă și indicii obiectelor alese, de la 1, fiecare cel mult o dată, cu greutate totală ≤ G.', 'Compară liniile succesive dp[i][c] pentru reconstrucție.', 'n, G = map(int, input().split())\na = [tuple(map(int, input().split())) for _ in range(n)]\ndp = [[0] * (G + 1) for _ in range(n + 1)]\nfor i, (g, v) in enumerate(a, 1):\n    for c in range(G + 1):\n        dp[i][c] = max(dp[i - 1][c], dp[i - 1][c - g] + v if g <= c else 0)\nprint(dp[n][G])\npath = []\nc = G\nfor i in range(n, 0, -1):\n    if dp[i][c] != dp[i - 1][c]:\n        path.append(i)\n        c -= a[i - 1][0]\nprint(*reversed(path))', [('3 5\n2 3\n3 4\n4 5','7\n1 2'),('0 0','0\n'),('2 2\n2 3\n2 3','3\n1')], 'Aplicare', validator='knapsack')
    add('dinamica', 'Segmentul de sumă maximă', 'Citește o listă nevidă. Afișează suma maximă a unui segment nevid și indicii l r de la 0 ai unui segment care o realizează.', 'Kadane alege între un început nou și prelungirea segmentului; păstrează începutul curent.', 'a = list(map(int, input().split()))\ncur = best = a[0]\nstart = left = right = 0\nfor i in range(1, len(a)):\n    if a[i] > cur + a[i]:\n        cur, start = a[i], i\n    else:\n        cur += a[i]\n    if cur > best:\n        best, left, right = cur, start, i\nprint(best)\nprint(left, right)', [('1 -2 3 -1 5 2 -6 1 3','9\n2 5'),('-8 -3 -5','-3\n1 1'),('0 0','0\n0 0')], 'Aplicare', validator='segment')
    add('dinamica', 'Subset sum prin DP', 'Citește numere naturale distincte și S între 0 și 10000. Afișează DA sau NU dacă există o submulțime de sumă S. Folosește DP, fiecare element cel mult o dată.', 'Parcurge sumele descrescător pentru fiecare element.', 'a = list(map(int, input().split()))\nS = int(input())\ndp = [True] + [False] * S\nfor x in a:\n    for s in range(S, x - 1, -1):\n        dp[s] = dp[s] or dp[s - x]\nprint("DA" if dp[S] else "NU")', [('12 1 3 4 5 7\n14','DA'),('2 4\n3','NU'),('\n0','DA')], 'Aplicare')
    add('dinamica', 'Împărțirea cadourilor', 'Citește cel mult 100 de valori pozitive, fiecare ≤ 100. Împarte cadourile între doi frați cu diferență minimă. Afișează diferența și indicii cadourilor primului frate; restul revin celui de-al doilea.', 'Găsește suma maximă ≤ total//2 prin subset sum și predecesori.', 'a = list(map(int, input().split()))\ntotal = sum(a)\nM = total // 2\ndp = [True] + [False] * M\npred = {}\nfor i, x in enumerate(a, 1):\n    for s in range(M, x - 1, -1):\n        if not dp[s] and dp[s - x]:\n            dp[s] = True\n            pred[s] = (s - x, i)\ns = max(i for i in range(M + 1) if dp[i])\nprint(total - 2 * s)\npath = []\nwhile s:\n    s, i = pred[s]\n    path.append(i)\nprint(*reversed(path))', [('28 7 11 8 9 7 27','1\n1 3 5'),('2 2','0\n1'),('\n','0\n')], 'Aprofundare', validator='partition')
    add('dinamica', 'Turnuri: optim și număr', 'Citește n și n perechi latură culoare, cu laturi pozitive posibil egale. Cuburile sunt distincte prin indice. Afișează înălțimea maximă și numărul turnurilor optime: laturile descresc strict, culorile vecine diferă. Pentru n=0 există un turn vid de înălțime 0.', 'Cu laturi repetate folosește DP. La egalitate de înălțime adună numărul variantelor.', 'n = int(input())\na = sorted(tuple(map(int, input().split())) for _ in range(n))\ndp = [s for s, c in a]\nways = [1] * n\nfor i in range(n):\n    for j in range(i):\n        if a[j][0] < a[i][0] and a[j][1] != a[i][1]:\n            v = a[i][0] + dp[j]\n            if v > dp[i]:\n                dp[i], ways[i] = v, ways[j]\n            elif v == dp[i]:\n                ways[i] += ways[j]\nbest = max(dp, default=0)\nprint(best, sum(ways[i] for i in range(n) if dp[i] == best) if n else 1)', [('3\n3 1\n2 2\n2 2','5 2'),('2\n4 1\n3 1','4 1'),('0','0 1')], 'Aprofundare')
    add('dinamica', 'Bilete de călătorie', 'Prima linie: zilele de călătorie distincte crescătoare din 1..365. A doua: prețurile pentru 1, 7 și 30 de zile. Afișează costul minim; zilele pot lipsi.', 'Compară cele trei abonamente care pot acoperi ziua curentă.', 'from bisect import bisect_left\na = list(map(int, input().split()))\ncost = list(map(int, input().split()))\ndp = [0] * (len(a) + 1)\nfor i, day in enumerate(a, 1):\n    dp[i] = min(dp[bisect_left(a, day - length + 1, 0, i)] + c for length, c in zip([1, 7, 30], cost))\nprint(dp[-1])', [('1 4 6 7 8 20\n2 7 15','11'),('\n2 7 15','0'),('1 2 3\n2 7 15','6')], 'Aprofundare')
    add('dinamica', 'Pătrate formate numai din 1', 'Citește n m și o matrice binară. Numără toate submatricele pătratice cu numai 1.', 'La o celulă 1, dimensiunea maximă este 1+min(sus,stânga,diagonală); starea numără și pătratele mai mici.', 'n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if a[i - 1][j - 1]:\n            dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])\nprint(sum(map(sum, dp)))', [('2 2\n1 1\n1 1','5'),('1 3\n1 0 1','2'),('2 2\n0 0\n0 0','0')], 'Aprofundare')
    add('dinamica', 'Joburi cu durate diferite', 'Citește n și n triplete profit termen durată, pozitive și cu termene ≤ 1000. Un job aduce profit numai terminat la timp. Afișează profitul maxim al unei submulțimi executate secvențial de la 0.', 'Sortează după termen și actualizează descrescător timpul exact ocupat, limitat de termen.', 'n = int(input())\na = [tuple(map(int, input().split())) for _ in range(n)]\na.sort(key=lambda x: x[1])\nT = max((d for p, d, l in a), default=0)\ndp = [0] + [-10 ** 9] * T\nfor p, d, l in a:\n    for t in range(d, l - 1, -1):\n        dp[t] = max(dp[t], dp[t - l] + p)\nprint(max(dp))', [('4\n3 5 3\n2 2 1\n3 2 2\n5 4 3','7'),('1\n9 1 2','0'),('0','0')], 'Aprofundare')
    add('dinamica', 'Jocul stânga–dreapta', 'Citește o listă de întregi. Doi jucători aleg alternativ un capăt și joacă optim. Afișează diferența maximă garantată primul minus al doilea. Pentru lista vidă afișează 0.', 'dp[l][r]=max(a[l]-dp[l+1][r],a[r]-dp[l][r-1]); semnul se schimbă odată cu jucătorul.', 'a = list(map(int, input().split()))\nn = len(a)\ndp = [[0] * n for _ in range(n)]\nfor i in range(n):\n    dp[i][i] = a[i]\nfor length in range(2, n + 1):\n    for l in range(n - length + 1):\n        r = l + length - 1\n        dp[l][r] = max(a[l] - dp[l + 1][r], a[r] - dp[l][r - 1])\nprint(dp[0][-1] if a else 0)', [('2 1 4 3','2'),('1 5 2','-2'),('\n','0')], 'Aprofundare')
    add('dinamica', 'O valoare din fiecare vector', 'Citește n k și n linii nevide de numere naturale pozitive. Alege exact un element din fiecare linie pentru suma k. Afișează DA sau NU folosind stări separate pentru fiecare vector.', 'La un nivel nou pornești numai din sumele nivelului anterior.', 'n, k = map(int, input().split())\nreachable = {0}\nfor _ in range(n):\n    a = list(map(int, input().split()))\n    reachable = {s + x for s in reachable for x in a if s + x <= k}\nprint("DA" if k in reachable else "NU")', [('3 11\n3 5 10 8\n4 3 7\n6 8 2 9','DA'),('2 5\n2\n2','NU'),('0 0','DA')], 'Aprofundare')
